const subtotal = $json.total;
const discountedTotal = $json.discountedTotal;

const discount = subtotal - discountedTotal;
const VAT = discountedTotal * 0.19;
const finalTotal = discountedTotal + VAT;

return {
  json: {
    ...$json,
    subtotal,
    discount,
    VAT,
    finalTotal
  }
};

// NODE 07 - Generate Invoice HTML

const order = $json;

// Helper for currency formatting
function money(value) {
  return Number(value || 0).toFixed(2);
}

// Current date
const date = new Date().toLocaleDateString('en-GB');

// Order information
const orderReference = order.order_reference || `ORD-${order.order_id}`;
const customerId = order.customer_id || 'N/A';
const currency = order.currency || 'EUR';

const subtotal = Number(order.subtotal || 0);
const discount = Number(order.discount || 0);
const vat = Number(order.vat || 0);
const total = Number(order.total || 0);
const quantity = Number(order.total_quantity || 0);

// Products
let productsHtml = '';

if (Array.isArray(order.products)) {
  productsHtml = order.products.map(product => `
    <tr>
      <td>${product.title || product.name || 'Product'}</td>
      <td>${product.quantity || 1}</td>
      <td>${money(product.price)} ${currency}</td>
      <td>${money(product.total || (product.price * product.quantity))} ${currency}</td>
    </tr>
  `).join('');
} else {
  productsHtml = `
    <tr>
      <td colspan="4" style="text-align:center;">
        Order contains ${quantity} item(s)
      </td>
    </tr>
  `;
}

// Generate HTML
const html = `
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">

<title>Order ${orderReference}</title>

<style>

    * {
        box-sizing: border-box;
    }

    body {
        font-family: Arial, Helvetica, sans-serif;
        background: #f4f6f8;
        margin: 0;
        padding: 40px;
        color: #333;
    }

    .invoice {
        width: 800px;
        margin: auto;
        background: white;
        padding: 45px;
        border-radius: 8px;
    }

    .header {
        display: flex;
        justify-content: space-between;
        align-items: flex-start;
        margin-bottom: 40px;
    }

    .company-name {
        font-size: 28px;
        font-weight: bold;
        color: #222;
    }

    .company-info {
        margin-top: 8px;
        color: #777;
        font-size: 13px;
        line-height: 1.6;
    }

    .invoice-title {
        text-align: right;
    }

    .invoice-title h1 {
        margin: 0;
        font-size: 32px;
        color: #222;
    }

    .invoice-title p {
        margin: 6px 0;
        color: #777;
        font-size: 13px;
    }

    .customer-section {
        display: flex;
        justify-content: space-between;
        margin-bottom: 35px;
        padding: 20px;
        background: #f8f9fa;
        border-radius: 6px;
    }

    .section-title {
        font-weight: bold;
        margin-bottom: 7px;
        color: #555;
        font-size: 13px;
        text-transform: uppercase;
    }

    .customer-info {
        font-size: 14px;
        line-height: 1.6;
    }

    table {
        width: 100%;
        border-collapse: collapse;
        margin-bottom: 30px;
    }

    th {
        text-align: left;
        padding: 12px;
        background: #222;
        color: white;
        font-size: 13px;
    }

    td {
        padding: 13px 12px;
        border-bottom: 1px solid #eee;
        font-size: 13px;
    }

    .summary {
        width: 320px;
        margin-left: auto;
    }

    .summary-row {
        display: flex;
        justify-content: space-between;
        padding: 8px 0;
        font-size: 14px;
    }

    .discount {
        color: #008000;
    }

    .total {
        border-top: 2px solid #222;
        margin-top: 10px;
        padding-top: 15px;
        font-size: 20px;
        font-weight: bold;
    }

    .status {
        display: inline-block;
        margin-top: 25px;
        padding: 7px 14px;
        background: #e8f5e9;
        color: #2e7d32;
        border-radius: 20px;
        font-size: 12px;
        font-weight: bold;
    }

    .footer {
        margin-top: 50px;
        padding-top: 20px;
        border-top: 1px solid #eee;
        text-align: center;
        color: #888;
        font-size: 12px;
        line-height: 1.6;
    }

</style>

</head>

<body>

<div class="invoice">

    <!-- HEADER -->

    <div class="header">

        <div>
            <div class="company-name">
                YOUR COMPANY
            </div>

            <div class="company-info">
                123 Business Street<br>
                Tunis, Tunisia<br>
                contact@yourcompany.com<br>
                +216 XX XXX XXX
            </div>
        </div>

        <div class="invoice-title">

            <h1>ORDER</h1>

            <p>
                <strong>${orderReference}</strong>
            </p>

            <p>
                Date: ${date}
            </p>

        </div>

    </div>


    <!-- CUSTOMER -->

    <div class="customer-section">

        <div>

            <div class="section-title">
                Customer
            </div>

            <div class="customer-info">
                Customer ID: ${customerId}
            </div>

        </div>


        <div>

            <div class="section-title">
                Order Status
            </div>

            <div class="customer-info">
                ${order.status || 'NEW'}
            </div>

        </div>

    </div>


    <!-- PRODUCTS -->

    <table>

        <thead>

            <tr>
                <th>Product</th>
                <th>Quantity</th>
                <th>Unit Price</th>
                <th>Total</th>
            </tr>

        </thead>

        <tbody>

            ${productsHtml}

        </tbody>

    </table>


    <!-- SUMMARY -->

    <div class="summary">

        <div class="summary-row">

            <span>Subtotal</span>

            <span>
                ${money(subtotal)} ${currency}
            </span>

        </div>


        <div class="summary-row discount">

            <span>Discount</span>

            <span>
                -${money(discount)} ${currency}
            </span>

        </div>


        <div class="summary-row">

            <span>VAT</span>

            <span>
                ${money(vat)} ${currency}
            </span>

        </div>


        <div class="summary-row total">

            <span>Total</span>

            <span>
                ${money(total)} ${currency}
            </span>

        </div>

    </div>


    <!-- STATUS -->

    <div class="status">

        ORDER ${order.status || 'NEW'}

    </div>


    <!-- FOOTER -->

    <div class="footer">

        Thank you for your order.

        <br>

        This document was automatically generated by our
        AI-powered order processing system.

        <br><br>

        © ${new Date().getFullYear()} Your Company

    </div>

</div>

</body>
</html>
`;

// Return data for the next node
return [
  {
    json: {
      ...order,

      invoice_html: html,

      invoice_filename: `${orderReference}.html`,

      pdf_filename: `${orderReference}.pdf`
    }
  }
];
